*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#a9d8f0;font-family:'DM Sans',sans-serif;color:#fff}button{font:inherit}#game{position:relative;width:100vw;height:100dvh;overflow:hidden;background:linear-gradient(#a9d8f0,#d2e8dd);isolation:isolate}#world{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(18,44,55,.24),transparent 20%,transparent 68%,rgba(23,43,30,.19));z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:88px;padding:24px 38px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(16,37,48,.25),transparent)}.brand-mark{display:flex;align-items:center;gap:12px}.brand-mark>div{display:flex;flex-direction:column;gap:3px}.brand-mark strong{font-size:12px;letter-spacing:.18em;font-weight:800;text-shadow:0 1px 5px #365b5f55}.brand-mark small{font:9px 'DM Mono',monospace;letter-spacing:.16em;opacity:.76}.brand-icon{height:28px;width:28px;display:grid;grid-template-columns:repeat(2,1fr);grid-template-rows:repeat(2,1fr);gap:2px;transform:rotate(-5deg)}.brand-icon i{display:block;background:#f4d57b;border-radius:2px;box-shadow:inset -2px -2px 0 #d9ae58}.brand-icon i:nth-child(2){background:#b4d58c;box-shadow:inset -2px -2px 0 #86af68}.brand-icon i:nth-child(3){background:#92bd77;box-shadow:inset -2px -2px 0 #6c985b}.brand-icon i:nth-child(4){background:#d9a968;box-shadow:inset -2px -2px 0 #b98550}.world-meta{height:34px;padding:0 14px;display:flex;align-items:center;gap:9px;border:1px solid rgba(255,255,255,.28);background:rgba(31,59,61,.19);border-radius:20px;backdrop-filter:blur(8px);font:10px 'DM Mono',monospace;letter-spacing:.08em;text-shadow:0 1px 4px #37555555}.live-dot{width:6px;height:6px;border-radius:50%;background:#c9e69e;box-shadow:0 0 9px #c9e69e}.meta-divider{height:12px;width:1px;background:rgba(255,255,255,.38);margin:0 3px}.coordinates{z-index:3;position:absolute;top:105px;left:39px;font:10px 'DM Mono',monospace;letter-spacing:.05em;text-shadow:0 1px 5px #395b5b}.coord-icon{font-size:16px;margin-right:8px;color:#f2dda4;vertical-align:-1px}.crosshair{z-index:2;position:absolute;top:50%;left:50%;width:18px;height:18px;transform:translate(-50%,-50%);opacity:.86;pointer-events:none}.crosshair:before,.crosshair:after{content:'';position:absolute;background:rgba(255,255,255,.88);box-shadow:0 1px 2px #38554d}.crosshair:before{width:2px;height:6px;left:8px;top:0}.crosshair:after{width:2px;height:6px;left:8px;bottom:0}.crosshair i,.crosshair b{position:absolute;background:rgba(255,255,255,.88);box-shadow:0 1px 2px #38554d}.crosshair i{width:6px;height:2px;left:0;top:8px}.crosshair b{width:6px;height:2px;right:0;top:8px}.target-name{position:absolute;z-index:3;top:calc(50% + 17px);left:50%;transform:translateX(-50%);font:9px 'DM Mono',monospace;letter-spacing:.12em;text-transform:uppercase;text-shadow:0 1px 5px #26443f;opacity:0;transition:opacity .15s}.target-name.visible{opacity:.82}.welcome{z-index:6;position:absolute;inset:0;display:grid;place-items:center;transition:opacity .5s,visibility .5s;overflow:hidden}.welcome.hidden{opacity:0;visibility:hidden;pointer-events:none}.welcome:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(17,42,45,.48),rgba(17,42,45,.13) 70%,rgba(17,42,45,.08))}.welcome-card{position:relative;z-index:1;width:min(420px,calc(100vw - 42px));margin-left:min(32vw,350px);padding:36px 39px 27px;background:rgba(25,49,48,.52);border:1px solid rgba(255,255,255,.25);border-radius:5px;backdrop-filter:blur(18px);box-shadow:0 22px 65px #1c3c3933;animation:rise .75s cubic-bezier(.2,.8,.2,1) both}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:.18em;color:#d9e8c1;display:flex;align-items:center;gap:9px}.eyebrow>span{display:inline-block;width:6px;height:6px;border-radius:50%;background:#d7e8a7;box-shadow:0 0 10px #d7e8a7}h1{font-size:clamp(42px,5vw,62px);letter-spacing:-.06em;line-height:.98;font-weight:600;margin:22px 0 15px}h1 em{font-family:Georgia,serif;font-weight:400;color:#dce7a8;letter-spacing:-.07em}.welcome-card p{max-width:290px;font-size:13px;line-height:1.75;color:#eef3e8;opacity:.84;margin:0 0 24px}.start-button{width:100%;height:48px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;border:0;border-radius:3px;background:#d9e8aa;color:#274239;cursor:pointer;font-size:12px;font-weight:700;letter-spacing:.02em;transition:transform .2s,background .2s}.start-button:hover{background:#e8f0c4;transform:translateY(-2px)}.start-button b{font-size:17px;font-weight:500}.welcome-foot{margin-top:20px;text-align:center;color:#e3e9d8;font:9px 'DM Mono',monospace;letter-spacing:.06em;opacity:.75}.welcome-foot span{color:#dfe9a6;margin-right:5px}.welcome-orbit{position:absolute;border:1px solid rgba(255,255,255,.17);border-radius:50%;pointer-events:none}.orbit-one{width:520px;height:520px;right:-110px;top:12%;}.orbit-two{width:700px;height:700px;right:-200px;top:3%;border-color:rgba(255,255,255,.1)}@keyframes rise{from{transform:translateY(12px);opacity:0}to{transform:translateY(0);opacity:1}}.controls-hint{position:absolute;z-index:3;bottom:137px;left:50%;transform:translateX(-50%);height:34px;display:flex;align-items:center;gap:9px;padding:0 13px;border-radius:3px;background:rgba(28,48,44,.3);border:1px solid rgba(255,255,255,.2);backdrop-filter:blur(8px);font-size:9px;color:#fff;text-shadow:0 1px 4px #29463c}.hint-key{display:flex;gap:2px}.hint-key span{width:15px;height:15px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.45);border-radius:2px;font:8px 'DM Mono',monospace}.hint-copy{white-space:nowrap;opacity:.9}.hint-sep{height:14px;width:1px;background:rgba(255,255,255,.3);margin:0 3px}.mouse-hint{font-size:14px}.controls-hint kbd,.help-card kbd{font:8px 'DM Mono',monospace;border:1px solid rgba(255,255,255,.4);border-radius:2px;padding:3px 4px;color:#fff}.hint-plus{opacity:.5;padding:0 3px}.hotbar{position:absolute;z-index:4;bottom:31px;left:50%;transform:translateX(-50%);display:flex;gap:5px;padding:7px;background:rgba(28,43,39,.63);border:1px solid rgba(255,255,255,.25);border-radius:5px;backdrop-filter:blur(12px);box-shadow:0 9px 28px #172e2c36}.slot{position:relative;width:47px;height:47px;border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.08);border-radius:3px;display:grid;place-items:center;cursor:pointer;transition:all .16s}.slot:hover{background:rgba(255,255,255,.18);transform:translateY(-2px)}.slot.selected{border:2px solid #e6edbe;background:rgba(222,235,184,.17);box-shadow:0 0 14px #e8efc44d}.slot-num{position:absolute;top:3px;left:5px;font:8px 'DM Mono',monospace;color:#e2ebdb;opacity:.75}.block-icon{width:23px;height:23px;position:relative;transform:rotate(-3deg);filter:drop-shadow(1px 2px 1px #152b284d)}.block-icon:before,.block-icon:after{content:'';position:absolute;inset:0;background:var(--block);border:1px solid rgba(0,0,0,.14);border-radius:2px}.block-icon:before{clip-path:polygon(0 20%,50% 0,100% 20%,50% 40%);background:var(--top)}.block-icon:after{clip-path:polygon(0 20%,50% 40%,50% 100%,0 78%);background:var(--left)}.block-icon span{position:absolute;inset:0;clip-path:polygon(50% 40%,100% 20%,100% 78%,50% 100%);background:var(--right);z-index:1}.selected-label{position:absolute;z-index:3;left:50%;bottom:96px;transform:translateX(-50%);display:flex;align-items:center;gap:7px;font:9px 'DM Mono',monospace;letter-spacing:.08em;text-shadow:0 1px 5px #29453c}.selected-swatch{height:7px;width:7px;border-radius:1px;background:#8fbd77;box-shadow:0 0 7px #c9e69e}.right-rail{z-index:4;position:absolute;right:27px;top:50%;transform:translateY(-50%);display:flex;flex-direction:column;gap:8px}.icon-button{width:31px;height:31px;border:1px solid rgba(255,255,255,.36);border-radius:50%;background:rgba(29,53,49,.24);color:#fff;font:12px 'DM Mono',monospace;cursor:pointer;backdrop-filter:blur(7px);transition:background .2s}.icon-button:hover{background:rgba(255,255,255,.23)}.help-card{display:none;position:absolute;z-index:8;right:27px;top:calc(50% + 25px);width:225px;padding:19px;background:rgba(25,48,46,.86);border:1px solid rgba(255,255,255,.25);border-radius:4px;backdrop-filter:blur(15px);box-shadow:0 10px 35px #19332e4a}.help-card.open{display:block}.help-card .eyebrow{margin-bottom:15px}.help-card ul{list-style:none;padding:0;margin:0;display:grid;gap:11px}.help-card li{display:flex;justify-content:space-between;align-items:center;font-size:10px;color:#edf2e8}.close-help{position:absolute;right:9px;top:7px;border:0;background:none;color:#fff;font-size:19px;cursor:pointer;opacity:.8}.toast{position:absolute;z-index:4;left:50%;top:20%;transform:translate(-50%,-5px);padding:8px 13px;background:rgba(28,48,44,.58);border:1px solid rgba(255,255,255,.22);border-radius:3px;font:9px 'DM Mono',monospace;letter-spacing:.06em;opacity:0;transition:opacity .2s,transform .2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.pause-screen{z-index:7;position:absolute;inset:0;display:grid;place-items:center;background:rgba(20,41,38,.22);backdrop-filter:blur(3px);opacity:0;visibility:hidden;transition:.3s}.pause-screen.visible{opacity:1;visibility:visible}.pause-card{width:min(330px,calc(100vw - 40px));padding:30px;background:rgba(26,49,47,.8);border:1px solid rgba(255,255,255,.25);border-radius:4px;text-align:center;box-shadow:0 20px 60px #19352e44}.pause-spark{font-size:22px;color:#e3ecb6}.pause-card h2{font-size:25px;letter-spacing:-.04em;margin:11px 0 7px}.pause-card p{font-size:12px;color:#dce8df;margin:0 0 22px}.pause-card .start-button{height:43px}.mobile-controls{display:none}.mobile-controls button{touch-action:none}.mobile-controls button:active{background:rgba(228,237,192,.38)}
@media(max-width:700px){.topbar{height:72px;padding:17px 17px}.brand-icon{width:24px;height:24px}.brand-mark strong{font-size:10px}.brand-mark small{font-size:7px}.world-meta{font-size:8px;padding:0 9px;height:29px;gap:6px}.coordinates{top:82px;left:18px;font-size:9px}.welcome-card{margin:0;padding:29px 27px 22px}.welcome:before{background:rgba(17,42,45,.25)}h1{font-size:49px}.welcome-card p{font-size:12px}.controls-hint{display:none}.hotbar{bottom:calc(96px + env(safe-area-inset-bottom));gap:3px;padding:5px}.slot{width:min(12vw,43px);height:min(12vw,43px)}.block-icon{width:21px;height:21px}.selected-label{bottom:calc(151px + env(safe-area-inset-bottom));font-size:8px}.right-rail{right:12px;top:83px;transform:none;flex-direction:row}.icon-button{width:29px;height:29px}.help-card{top:120px;right:12px}.mobile-controls{position:absolute;z-index:4;display:flex;left:16px;right:16px;bottom:calc(14px + env(safe-area-inset-bottom));justify-content:space-between;align-items:end;pointer-events:none}.dpad,.mobile-actions{pointer-events:auto}.dpad button,.mobile-actions button{border:1px solid rgba(255,255,255,.3);background:rgba(28,48,44,.42);color:white;backdrop-filter:blur(8px);border-radius:50%;width:39px;height:39px;font-size:17px}.dpad>button{display:block;margin:auto auto 3px}.dpad div{display:flex;gap:3px}.mobile-actions{display:flex;gap:7px}.mobile-actions button{width:48px;height:48px;font-size:15px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px}.mobile-actions small{font:7px 'DM Mono',monospace;letter-spacing:.05em}.pause-card{padding:26px}.vignette{background:linear-gradient(180deg,rgba(18,44,55,.2),transparent 18%,transparent 65%,rgba(23,43,30,.2))}}
@media(max-height:560px) and (min-width:701px){.welcome-card{padding:23px 30px}.welcome-card h1{font-size:45px;margin:15px 0 9px}.welcome-card p{margin-bottom:14px}.welcome-foot{margin-top:12px}.hotbar{bottom:13px}.selected-label{bottom:72px}.controls-hint{bottom:120px}}

import * as THREE from 'three';

const canvas = document.querySelector('#world');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#b6d9e8');
scene.fog = new THREE.Fog('#b6d9e8', 23, 68);
const camera = new THREE.PerspectiveCamera(70, innerWidth / innerHeight, .1, 120);
const renderer = new THREE.WebGLRenderer({canvas, antialias:true, powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.13;

scene.add(new THREE.HemisphereLight(0xe4f6ff, 0x657853, 2.0));
const sun = new THREE.DirectionalLight(0xffedc4, 3.25);
sun.position.set(-15, 27, -10);
sun.castShadow = true;
sun.shadow.mapSize.set(1024,1024);
sun.shadow.camera.left = -26; sun.shadow.camera.right = 26; sun.shadow.camera.top = 26; sun.shadow.camera.bottom = -26;
sun.shadow.bias = -.0005;
scene.add(sun);

const palette = {
  grass:{label:'Mossy grass',ui:['#8fbd77','#78a966','#a9ce8a','#688d5e'], top:'#8fbd77', side:'#78a966'},
  dirt:{label:'Warm earth',ui:['#a97850','#805738','#bd8b5e','#6e4b39'],top:'#a97850',side:'#805738'},
  stone:{label:'Soft stone',ui:['#a7aaa0','#81867d','#c0c3b9','#6d716c'],top:'#a7aaa0',side:'#81867d'},
  wood:{label:'Honey wood',ui:['#b17b4c','#875b3b','#c89560','#704b34'],top:'#b17b4c',side:'#875b3b'},
  leaves:{label:'Leafy green',ui:['#78a768','#5d8951','#98bf78','#4c7448'],top:'#78a768',side:'#5d8951'},
  sand:{label:'Pale sand',ui:['#e2cb8e','#c5ad70','#f0dfa9','#ab955f'],top:'#e2cb8e',side:'#c5ad70'}
};
const keys = Object.keys(palette);
const blockMaterials = {};
for (const [type,p] of Object.entries(palette)) {
  const mat = (color) => new THREE.MeshStandardMaterial({color, roughness:1});
  blockMaterials[type] = [mat(p.side),mat(p.ui[3]),mat(p.top),mat(p.ui[3]),mat(p.side),mat(p.ui[1])];
}
const cube = new THREE.BoxGeometry(1,1,1);
const blocks = new Map();
const meshes = new Map();
const keyOf = (x,y,z)=>`${x},${y},${z}`;
function addBlock(x,y,z,type, special=false) {
  const k=keyOf(x,y,z); if(blocks.has(k)) return false;
  blocks.set(k,{x,y,z,type,special});
  const mesh=new THREE.Mesh(cube,blockMaterials[type]);
  mesh.position.set(x+.5,y+.5,z+.5); mesh.castShadow=true; mesh.receiveShadow=true;
  mesh.userData={key:k,type}; scene.add(mesh); meshes.set(k,mesh);
  return true;
}
function removeBlock(x,y,z) {
  const k=keyOf(x,y,z), m=meshes.get(k); if(!m) return null;
  scene.remove(m); meshes.delete(k); const b=blocks.get(k); blocks.delete(k); return b;
}
const terrainHeight=(x,z)=>Math.max(1,Math.min(4,Math.floor(2.6+Math.sin(x*.27)*.62+Math.cos(z*.24)*.5+Math.sin((x+z)*.17)*.45)));
// Gentle rolling island, layered in earthy voxel strata.
for(let x=-22;x<=22;x++) for(let z=-22;z<=22;z++) {
  const edge=Math.max(Math.abs(x),Math.abs(z));
  if(edge>20 && ((x*17+z*13)%5!==0)) continue;
  const h=terrainHeight(x,z);
  for(let y=0;y<=h;y++) {
    const type=y===h?'grass':y>=h-2?'dirt':'stone';
    addBlock(x,y,z,type);
  }
}
// Soft sandy shoreline and a quiet, shallow pool.
for(let x=-22;x<=22;x++) for(let z=-22;z<=22;z++) {
  if(Math.abs(x)>19||Math.abs(z)>19) {
    const h=terrainHeight(x,z);
    const k=keyOf(x,h,z), b=blocks.get(k);
    if(b) { b.type='sand'; meshes.get(k).material=blockMaterials.sand; meshes.get(k).userData.type='sand'; }
  }
}
const water=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshStandardMaterial({color:0x84c8d1,roughness:.27,metalness:.05,transparent:true,opacity:.72}));
water.rotation.x=-Math.PI/2; water.position.y=1.38; water.position.z=-.5; scene.add(water);
// A few cubic trees make a welcoming little grove.
function tree(x,z,size=1) {
  const ground=terrainHeight(x,z);
  const trunkH=3+Math.floor(size*1.5);
  for(let y=ground+1;y<=ground+trunkH;y++) addBlock(x,y,z,'wood',true);
  const top=ground+trunkH;
  for(let dy=-1;dy<=2;dy++) {
    const radius=dy===2?1:dy===-1?1:2;
    for(let dx=-radius;dx<=radius;dx++) for(let dz=-radius;dz<=radius;dz++) {
      if(Math.abs(dx)+Math.abs(dz)>radius*2-1) continue;
      if(dx===0&&dz===0&&dy<1) continue;
      if(Math.abs(dx)+Math.abs(dz)+Math.abs(dy)*.8>4.1) continue;
      addBlock(x+dx,top+dy,z+dz,'leaves',true);
    }
  }
}
[[7,4,1],[10,7,.8],[-8,6,.9],[-11,10,1],[5,-10,.9],[-7,-11,.8],[13,-4,.8],[-14,-3,1],[2,13,.75]].forEach(v=>tree(...v));
// Simple flower tufts: tiny jewel-colored cubes on the meadow.
const flowers=[];
for(let i=0;i<38;i++) {
  const x=Math.floor(Math.sin(i*12.98)*13),z=Math.floor(Math.cos(i*7.31)*13);
  if(Math.abs(x)<3&&Math.abs(z)<3) continue;
  const y=terrainHeight(x,z)+1;
  const color=['#f6d989','#f2a9a0','#d3c7f1','#f5eee0'][i%4];
  const f=new THREE.Mesh(new THREE.BoxGeometry(.13,.16,.13),new THREE.MeshStandardMaterial({color,roughness:.8}));
  f.position.set(x+.5,y+.64,z+.5); f.castShadow=true; scene.add(f); flowers.push(f);
}
// Distant blocky clouds add scale and softness to the horizon.
const cloudMat=new THREE.MeshStandardMaterial({color:'#f5fbf4',roughness:1});
for(const [x,y,z,s] of [[-17,14,-20,1.3],[6,17,-24,1.7],[21,13,-12,1.1],[-25,16,2,1.5],[19,16,19,1.2]]) {
  for(let i=0;i<4;i++){const c=new THREE.Mesh(cube,cloudMat);c.scale.set(2.7*s, .55*s, .9*s);c.position.set(x+(i-1.5)*1.6*s,y+(i%2)*.28,z);scene.add(c);}
}

const inventory=Object.fromEntries(keys.map(k=>[k,18]));
let selected='grass';
const hotbar=document.querySelector('#hotbar');
const selectedName=document.querySelector('#selectedName');
const selectedSwatch=document.querySelector('.selected-swatch');
function buildHotbar(){
  hotbar.innerHTML='';
  keys.forEach((type,index)=>{
    const slot=document.createElement('button'); slot.className='slot'+(type===selected?' selected':'');slot.setAttribute('aria-label',`${index+1}: ${palette[type].label}, ${inventory[type]} blocks`);
    const [top,left,right]=palette[type].ui;
    slot.innerHTML=`<span class="slot-num">${index+1}</span><span class="block-icon" style="--block:${palette[type].side};--top:${top};--left:${left};--right:${right}"><span></span></span><span class="count">${inventory[type]}</span>`;
    slot.addEventListener('click',()=>selectBlock(type));hotbar.append(slot);
  });
  selectedName.textContent=palette[selected].label;selectedSwatch.style.background=palette[selected].top;
}
function selectBlock(type){selected=type;buildHotbar();}
buildHotbar();

const player={x:.5,z:.5,y:0,vy:0,yaw:Math.PI*.15,pitch:-.12,onGround:false};
const playerHeight=1.62, moveSpeed=5.1;
function groundAt(x,z){return terrainHeight(Math.floor(x),Math.floor(z))+1;}
player.y=groundAt(player.x,player.z)+playerHeight;
const keysDown=new Set();
let locked=false,started=false,toastTimer;
const welcome=document.querySelector('#welcome'),pause=document.querySelector('#pauseScreen');
function notify(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1700);}
function requestLock(){if(!isTouch)canvas.requestPointerLock?.();}
const isTouch=('ontouchstart' in window)||navigator.maxTouchPoints>0;
function begin(){started=true;welcome.classList.add('hidden');if(!isTouch)requestLock();else notify('Use the arrows to wander');}
document.querySelector('#startButton').addEventListener('click',begin);
document.querySelector('#resumeButton').addEventListener('click',()=>{pause.classList.remove('visible');if(!isTouch)requestLock();});
document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===canvas;if(locked){pause.classList.remove('visible');}else if(started&&!isTouch&&!welcome.classList.contains('hidden')){}else if(started&&!isTouch){pause.classList.add('visible');}});
window.addEventListener('keydown',e=>{
  if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)) e.preventDefault();
  keysDown.add(e.code);
  if(e.code.startsWith('Digit')){const i=Number(e.code.slice(5))-1;if(keys[i])selectBlock(keys[i]);}
  if(e.code==='Space'&&player.onGround){player.vy=7.1;player.onGround=false;}
  if(e.code==='Escape'&&isTouch&&started)pause.classList.toggle('visible');
});
window.addEventListener('keyup',e=>keysDown.delete(e.code));
window.addEventListener('blur',()=>keysDown.clear());
document.addEventListener('mousemove',e=>{if(locked){player.yaw-=e.movementX*.0022;player.pitch=Math.max(-1.35,Math.min(1.25,player.pitch-e.movementY*.0022));}});

const raycaster=new THREE.Raycaster();raycaster.far=6;
let target=null;
function aim(){
  raycaster.setFromCamera(new THREE.Vector2(0,0),camera);
  const hits=raycaster.intersectObjects([...meshes.values()],false);
  target=hits.length?hits[0]:null;
  const label=document.querySelector('#targetName');
  if(target){label.textContent=palette[target.object.userData.type]?.label||'';label.classList.add('visible');}else label.classList.remove('visible');
}
function dig(){
  aim();if(!target)return;
  const data=target.object.userData, block=blocks.get(data.key);if(!block)return;
  if(block.y===0){notify('The ground holds this little world together');return;}
  const removed=removeBlock(block.x,block.y,block.z);if(!removed)return;
  if(!removed.special&&inventory[removed.type]!==undefined)inventory[removed.type]=Math.min(99,inventory[removed.type]+1);
  buildHotbar();
}
function place(){
  aim();if(!target){notify('Find a spot for your block');return;}
  if(inventory[selected]<=0){notify('Gather a few blocks first');return;}
  const p=target.object.position, n=target.face.normal;
  const x=Math.floor(p.x+n.x*.51),y=Math.floor(p.y+n.y*.51),z=Math.floor(p.z+n.z*.51);
  if(Math.hypot((x+.5)-player.x,(z+.5)-player.z)<.8 && y<player.y+.3&&y+1>player.y-playerHeight){notify('A little too close to place');return;}
  if(addBlock(x,y,z,selected)){inventory[selected]--;buildHotbar();}
}
